1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	
4	const ZIMM_SIZE_CHIP_RECIPE = 'ZimmSizeChip';
5	
6	type ZimmSizeChipProps = {
7	  /** Underlying size value used for selection/comparison (e.g. an SFCC variation value). */
8	  value: string;
9	  /** Visible/accessible label rendered inside the chip (e.g. "S", "M", "42"). */
10	  label: string;
11	  /** Whether this is the currently selected size. */
12	  isSelected: boolean;
13	  /**
14	   * Whether this size is unavailable. Sets the real native `disabled` attribute so the chip is
15	   * genuinely inert for both mouse and assistive tech, not just visually greyed.
16	   */
17	  isDisabled?: boolean;
18	  /**
19	   * Whether this chip is reachable via Tab (`tabIndex={0}`) vs. removed from the tab order
20	   * (`tabIndex={-1}`) — the caller (ZimmSizeChipGroup) drives a roving tabindex across the row.
21	   * Mirrors ZimmColourSwatch's identical prop, for the identical reason.
22	   */
23	  isFocusable: boolean;
24	  /** Selection callback, called with `value` on click. Never called when `isDisabled` is true. */
25	  onSelect: (value: string) => void;
26	};
27	
28	/**
29	 * Atom — a single size option in a PDP size-chip row: a 28x28 button with radio semantics (one
30	 * selection out of the group). Purely presentational — no data-fetching hook, no keyboard
31	 * orchestration (that lives in the parent ZimmSizeChipGroup, matching the ZimmColourSwatch /
32	 * ZimmColourSwatchGroup split).
33	 */
34	export const ZimmSizeChip = ({ value, label, isSelected, isDisabled, isFocusable, onSelect }: ZimmSizeChipProps) => {
35	  const styles = useMultiStyleConfig(ZIMM_SIZE_CHIP_RECIPE, { selected: isSelected, disabled: isDisabled });
36	
37	  return (
38	    <chakra.button
39	      __css={styles.chip}
40	      type="button"
41	      role="radio"
42	      aria-checked={isSelected}
43	      disabled={isDisabled}
44	      tabIndex={isFocusable ? 0 : -1}
45	      data-testid="size-chip"
46	      data-size-value={value}
47	      onClick={() => {
48	        // Belt-and-braces: the native `disabled` attribute above already prevents the browser
49	        // from ever dispatching this click, but stating the invariant explicitly means a reader
50	        // doesn't have to recall that fact to trust onSelect can't fire for a disabled chip.
51	        if (!isDisabled) onSelect(value);
52	      }}
53	    >
54	      {label}
55	    </chakra.button>
56	  );
57	};
58	
59	export type { ZimmSizeChipProps };
60	export default ZimmSizeChip;
